lect * , row_number() over (partition by lower(facility) order by 1) rw from MAPLEMONK.facility_pincode ) where rw = 1 ) fa on lower(ufi.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM MAPLEMONK.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(EEFI.shipping_status, UFI.shipping_status, afi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) LEFT JOIN MAPLEMONK.category_mapping cm on upper(cm.category) = upper(afi.product_category) UNION ALL SELECT NULL AS customer_id ,UPPER(SHOP_NAME) AS SHOP_NAME ,UPPER(marketplace) AS marketplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,contact_num AS PHONE ,customer_name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,UPPER(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS City ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS Order_Status ,cast(cast(ORDER_DATE as datetime) as date) AS Order_Date ,CAST(ORDER_DATE AS datetime) AS ORDER_TIMESTAMP ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) + IFNULL(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_Order_Status ,UPPER(b.Shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID AS SALEORDERITEMCODE ,suborder_id AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS Payment_Gateway ,payment_mode AS Payment_Mode ,UPPER(COURIER) AS COURIER ,MANIFEST_DATE AS DISPATCH_DATE ,DELIVERED_DATE ,CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN IFNULL(is_refund, 0) END AS returned_sales ,CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,cast(Days_in_shipment as INT64) AS DAYS_IN_SHIPMENT ,NULL AS ACQUISITION_DATE ,SKU AS SKU_CODE ,UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL ,UPPER(coalesce(cm.final_category,b.mapped_category)) AS PRODUCT_CATEGORY ,null AS PRODUCT_SUB_CATEGORY ,b.commonsku ,UPPER(WAREHOUSE_NAME) AS WAREHOUSE ,pincode ,pickup_pincode ,null as discount_codes ,b.cost ,b.tax_rate FROM MAPLEMONK.P_TAL_DB_EasyEcom_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM MAPLEMONK.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) LEFT JOIN MAPLEMONK.category_mapping cm on upper(cm.category) = upper(b.mapped_category) WHERE not(LOWER(marketplace) LIKE \'%shopify%\' or LOWER(marketplace) LIKE ANY (\'%amazon%\', \'%gofynd\')) and reference_code not in (select distinct reference_code from MAPLEMONK.P_TAL_DB_unicommerce_fact_items) UNION ALL SELECT NULL AS customer_id ,UPPER(marketplace) AS shop_name ,UPPER(marketplace) AS marektplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,phone AS PHONE ,name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS city ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS order_status ,CAST(ORDER_DATE AS DATE) AS Order_Date ,CAST(ORDER_DATE AS datetime) ORDER_TIME ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) AS gross_sales_before_tax ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_ORDER_STATUS ,UPPER(b.shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,saleOrderItemCode AS SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS payment_gateway ,payment_mode ,COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date AS delivered_date ,CASE WHEN UPPER(FINAL_SHIPPING_STATUS) IN (\'DELIVERED\') THEN 1 END AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,CASE WHEN return_flag = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN return_flag = 1 THEN CAST(selling_price AS FLOAT64) END AS returned_sales ,CASE WHEN return_flag = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,CASE WHEN order_status = \'COMPLETE\' THEN date_diff(CAST(delivered_date AS DATE), CAST(order_date AS DATE),day) ELSE date_diff(CURRENT_DATE(), CAST(order_date AS DATE),day) END AS days_in_shipment ,NULL AS ACQUISITION_DATE ,sku_code ,UPPER(b.product_name_final) AS PRODUCT_NAME_FINAL ,UPPER(coalesce(cm.final_category,b.Product_Category)) AS PRODUCT_CATEGORY ,UPPER(b.product_sub_category) AS PRODUCT_SUB_CATEGORY ,SKU_code ,UPPER(warehouse_name) AS warehouse ,b.pincode ,fa.pincode source_pincode ,null discount_codes ,cast(null as int64) cost ,cast(null as int64) tax_rate FROM MAPLEMONK.P_TAL_DB_unicommerce_fact_items b left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from MAPLEMONK.facility_pincode ) where rw = 1 ) fa on lower(b.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM MAPLEMONK.shipment_status_mapping ) ShipMap WHERE ShipMap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) LEFT JOIN MAPLEMONK.category_mapping cm on upper(cm.category) = upper(b.product_category) WHERE NOT (LOWER(b.marketplace) LIKE ANY (\'%shopify%\') or LOWER(b.marketplace) LIKE ANY (\'%amazon%\')) ; Create or Replace Table MAPLEMONK.P_TAL_DB_sales_consolidated_intermediate as select sc.*, title as PRODUCT_NAME_FINAL , Master_SKU as commonsku ,upper(coalesce(pmu.State_Name,pmi.DELIVERY_STATE)) as State ,upper(coalesce(DELIVERY_CITY,Raw_CITY)) as City ,upper(ee.country) Country from MAPLEMONK.P_TAL_DB_sales_consolidated_intermediate sc left join ( select marketplace_sku,Master_SKU, Title from `maplemonk.P_TAL_FINAL_SKU_MASTER` )cd on lower(trim(cd.marketplace_sku)) = trim(lower(sc.sku)) LEFT JOIN ( SELECT * FROM `MapleMonk.P_TAL_DB_Pincode_Mapping_USA` QUALIFY ROW_NUMBER() OVER(PARTITION BY ZIP_Code_Range ORDER BY 1) = 1 ) pmu ON SAFE_CAST(sc.pincode AS INT64) >= SAFE_CAST(pmu.ZipCOde_Start AS INT64) AND SAFE_CAST(sc.pincode AS INT64) <= SAFE_CAST(pmu.ZipCOde_End AS INT64) AND LOWER(sc.marketplace) LIKE \'%usa%\' LEFT JOIN ( SELECT * FROM `MapleMonk.P_TAL_DB_Pincode_Mapping_india` QUALIFY ROW_NUMBER() OVER(PARTITION BY DELIVERY_POSTCODE ORDER BY 1) = 1 ) pmi ON SAFE_CAST(sc.pincode AS INT64) = SAFE_CAST(pmi.DELIVERY_POSTCODE AS INT64) left join ( select reference_code,country from MAPLEMONK.P_TAL_DB_EasyEcom_FACT_ITEMS qualify row_number() over(partition by lower(trim(reference_code)) order by 1) = 1 )ee on replace(lower(trim(ee.reference_code)),\'#\',\'\') = replace(lower(trim(sc.reference_code)),\'#\',\'\') ; CREATE OR REPLACE TABLE MAPLEMONK.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM MAPLEMONK.P_TAL_DB_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM MAPLEMONK.P_TAL_DB_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE MAPLEMONK.P_TAL_DB_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, case WHEN upper(m.final_shipping_status) LIKE \'%RTO%\' OR upper(m.final_shipping_status) LIKE \'%FAILURE%\' OR upper(m.order_status) LIKE \'%UNFULFILLABLE%\' OR upper(m.order_status) LIKE \'%RETURNED TO SELLER%\' OR upper(m.order_status) LIKE \'%RETURNING TO SELLER%\' OR upper(m.order_status) LIKE \'%UNDELIVERED%\' OR (upper(m.order_status) LIKE \'%CANCEL%\' AND upper(m.final_shipping_status) = \'IN TRANSIT\') THEN 1 ELSE 0 end as RTO_flag, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then 1 else 0 end as DTO_flag, case when upper(m.final_shipping_status) like \'%RTO%\' or upper(m.final_shipping_status) like \'%FAILURE%\' or upper(m.order_status) like \'%UNFULFILLABLE%\' or upper(m.order_status) like \'%RETURNED TO SELLER%\' or upper(m.order_status) like \'%RETURNING TO SELLER%\' or upper(m.order_status) like \'%UNDELIVERED%\' or (upper(m.order_status) like \'%CANCEL%\' and upper(m.final_shipping_status) = \'IN TRANSIT\') then m.selling_price ELSE 0 end as RTO_value, case when (upper(m.final_shipping_status) like \'%RETURN%\' or upper(m.order_status) = \'RETURNED\') then m.selling_price else 0 end as DTO_value, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM MAPLEMONK.P_TAL_DB_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM MAPLEMONK.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM MAPLEMONK.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN MAPLEMONK.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace); ALTER TABLE MAPLEMONK.P_TAL_DB_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE MAPLEMONK.P_TAL_DB_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE MAPLEMONK.P_TAL_DB_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM MAPLEMONK.P_TAL_DB_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE MAPLEMONK.P_TAL_DB_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE MAPLEMONK.P_TAL_DB_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM MAPLEMONK.P_TAL_DB_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE MAPLEMONK.P_TAL_DB_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM MAPLEMONK.P_TAL_DB_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE MAPLEMONK.P_TAL_DB_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE MAPLEMONK.P_TAL_DB_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM MAPLEMONK.P_TAL_DB_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE MAPLEMONK.P_TAL_DB_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; Create Or Replace Table MAPLEMONK.P_TAL_DB_sales_consolidated as SELECT final_marketplace, customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, RTO_flag, DTO_flag, RTO_value, DTO_value, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, PHONE, NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, PAYMENT_GATEWAY, Payment_Mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, discount_codes, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, cast(null as int64) as Original_Return_Value, cast(null as string) as Return_Reference_Code, \'Sale\' as TYPE, country, cost ,tax_rate from MAPLEMONK.P_TAL_DB_sales_consolidated UNION ALL SELECT CAST(NULL AS STRING) AS final_marketplace, CAST(NULL AS INT64) AS customer_id_final, CAST(NULL AS DATE) AS acquisition_date, CAST(NULL AS DATE) AS first_complete_order_date, CAST(NULL AS FLOAT64) AS Order_Quantity, CAST(NULL AS INT64) AS RTO_flag, CAST(NULL AS INT64) AS DTO_flag, CAST(NULL AS FLOAT64) AS RTO_value, CAST(NULL AS FLOAT64) AS DTO_value, CAST(NULL AS INT64) AS maple_monk_id_phone, CAST(NULL AS STRING) AS customer_id, upper(marketplace_New) AS SHOP_NAME, upper(marketplace_New) AS marketplace, CAST(channel AS STRING) AS CHANNEL, CAST(channel AS STRING) AS SOURCE, CAST(NULL AS STRING) AS ORDER_ID, CAST(NULL AS STRING) AS reference_code, CAST(NULL AS STRING) AS PHONE, CAST(NULL AS STRING) AS NAME, CAST(NULL AS STRING) AS EMAIL, CAST(NULL AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, CAST(NULL AS STRING) AS SKU, CAST(NULL AS STRING) AS PRODUCT_ID, CAST(NULL AS STRING) AS PRODUCT_NAME, CAST(NULL AS STRING) AS CURRENCY, CAST(CITY AS STRING) AS CITY, CAST(STATE AS STRING) AS State, CAST(NULL AS STRING) AS ORDER_STATUS, CAST(RETURN_DATE AS DATE) AS Order_Date, DATETIME(CAST(NULL AS TIMESTAMP)) AS Order_Time, CAST(NULL AS FLOAT64) AS QUANTITY, CAST(NULL AS FLOAT64) AS GROSS_SALES_BEFORE_TAX, CAST(NULL AS FLOAT64) AS DISCOUNT, CAST(NULL AS FLOAT64) AS TAX, CAST(NULL AS FLOAT64) AS SHIPPING_PRICE, CAST(NULL AS FLOAT64) AS SELLING_PRICE, CAST(NULL AS STRING) AS OMS_order_status, CAST(NULL AS STRING) AS SHIPPING_STATUS, CAST(NULL AS STRING) AS FINAL_SHIPPING_STATUS, CAST(NULL AS STRING) AS SALEORDERITEMCODE, CAST(NULL AS STRING) AS SALES_ORDER_ITEM_ID, CAST(NULL AS STRING) AS AWB, CAST(PAYMENT_GATEWAY AS STRING) AS PAYMENT_GATEWAY, CAST(Payment_Mode AS STRING) AS Payment_Mode, CAST(NULL AS STRING) AS COURIER, CAST(NULL AS DATE) AS DISPATCH_DATE, CAST(NULL AS DATE) AS DELIVERED_DATE, CAST(NULL AS INT64) AS DELIVERED_STATUS, CAST(NULL AS INT64) AS RETURN_FLAG, CAST(NULL AS FLOAT64) AS returned_quantity, CAST(NULL AS FLOAT64) AS returned_sales, CAST(NULL AS FLOAT64) AS cancelled_quantity, CAST(NULL AS INT64) AS Days_in_Shipment, CAST(NULL AS DATE) AS MARKETPLACE_ACQUISITION_DATE, CAST(NULL AS STRING) AS SKU_CODE, CAST(productNameNew AS STRING) AS PRODUCT_NAME_FINAL, CAST(null AS STRING) AS PRODUCT_CATEGORY, CAST(null AS STRING) AS PRODUCT_SUB_CATEGORY, CAST(common_SKU AS STRING) AS commonsku, CAST(NULL AS STRING) AS WAREHOUSE, CAST(NULL AS STRING) AS pincode, CAST(NULL AS STRING) AS source_pincode, CAST(NULL AS STRING) AS discount_codes, CAST(NULL AS STRING) AS new_customer_flag, CAST(NULL AS STRING) AS new_customer_flag_month, CAST(NULL AS STRING) AS acquisition_product, CAST(NULL AS STRING) AS acquisition_channel, CAST(NULL AS STRING) AS acquisition_marketplace, RETURN_AMOUNT_WITHOUT_TAX_NEW as Original_Return_Value, reference_code as Return_Reference_Code, \'Return\' as Type, country, cast(null as float64) cost , cast(null as float64) tax_rate from ( ( select ri.reference_code, cast(ri.RETURN_DATE as Date) RETURN_DATE, sc.marketplace as marketplace_New, Master_SKU as common_SKU, channel, title as productNameNew, city, state, country, Payment_Mode, PAYMENT_GATEWAY, case when lower(sc.marketplace) like any (\'AMAZON USA\', \'WEBSITE USA\') then ifnull(RETURN_AMOUNT_WITHOUT_TAX,0) * ifnull(Close,85) else ifnull(RETURN_AMOUNT_WITHOUT_TAX,0) end as RETURN_AMOUNT_WITHOUT_TAX_NEW FROM MAPLEMONK.P_TAL_DB_easyecom_returns_intermediate ri left join ( select reference_code,marketplace,channel,city,state,country,Payment_Mode,PAYMENT_GATEWAY from MAPLEMONK.P_TAL_DB_sales_consolidated qualify row_number() over(partition by reference_code order by 1) = 1 )sc on lower(trim(replace(sc.reference_code,\'#\',\'\'))) = lower(trim(replace(ri.reference_code,\'#\',\'\'))) left join ( select marketplace_sku,Master_SKU, Title from `maplemonk.P_TAL_FINAL_SKU_MASTER` )cd on lower(trim(cd.marketplace_sku)) = trim(lower(ri.sku)) LEFT JOIN ( SELECT DATE(PARSE_TIMESTAMP(\'%m/%d/%Y %H:%M:%S\', Date)) AS rate_date, SAFE_CAST(Close AS FLOAT64) AS Close FROM Maplemonk.Google_sheet_USD_INR_Conversion_Rate qualify row_number() over(partition by DATE(PARSE_TIMESTAMP(\'%m/%d/%Y %H:%M:%S\', Date)) order by 1 desc)= 1 ) gr ON DATE(ri.order_date) = gr.rate_date ) UNION ALL ( select ri.reference_code, ri.RETURN_DATE, sc.marketplace as marketplace_New, Master_SKU as common_SKU, channel, title as productNameNew, city, state, country, Payment_Mode, PAYMENT_GATEWAY, (safe_divide(ifnull(sc.selling_price,0) , ifnull(sc.QUANTITY,0)) *(ri.quantity)) as RETURN_AMOUNT_WITHOUT_TAX_NEW FROM ( select date(cast(return_date as timestamp)) RETURN_DATE, asin, UPPER(sku) AS sku , Order_ID as reference_code, ifnull(cast(quantity as int64),0) as quantity from `MapleMonk.P_TAL_DB_GET_FBA_FULFILLMENT_CUSTOMER_RETURNS_DATA` Qualify row_number() over(partition by Order_ID,UPPER(sku) order by 1 ) = 1 ) ri left join ( select reference_code ,sku ,marketplace ,channel ,QUANTITY ,SELLING_PRICE ,city ,state ,country ,Payment_Mode ,PAYMENT_GATEWAY from MAPLEMONK.P_TAL_DB_sales_consolidated qualify row_number() over(partition by reference_code,sku order by 1) = 1 )sc on lower(trim(replace(sc.reference_code,\'#\',\'\'))) = lower(trim(replace(ri.reference_code,\'#\',\'\'))) and lower(trim((sc.sku))) = lower(trim((ri.sku))) left join ( select marketplace_sku,Master_SKU, Title from `maplemonk.P_TAL_FINAL_SKU_MASTER` )cd on lower(trim(cd.marketplace_sku)) = trim(lower(ri.sku)) ) UNION ALL ( select ri.reference_code, ri.RETURN_DATE, sc.marketplace as marketplace_New, Master_SKU as common_SKU, channel, title as productNameNew, city, state, country, Payment_Mode, PAYMENT_GATEWAY, (safe_divide(ifnull(sc.selling_price,0) , ifnull(sc.QUANTITY,0)) *(ri.quantity)) as RETURN_AMOUNT_WITHOUT_TAX_NEW FROM ( select date(cast(return_date as timestamp)) RETURN_DATE, asin, UPPER(sku) AS sku , Order_ID as reference_code, ifnull(cast(quantity as int64),0) as quantity from `MapleMonk.P_TAL_DB_IN_GET_FBA_FULFILLMENT_CUSTOMER_RETURNS_DATA` Qualify row_number() over(partition by Order_ID,UPPER(sku) order by 1 ) = 1 ) ri left join ( select reference_code ,sku ,marketplace ,channel ,QUANTITY ,SELLING_PRICE ,city ,state ,country ,Payment_Mode ,PAYMENT_GATEWAY from MAPLEMONK.P_TAL_DB_sales_consolidated qualify row_number() over(partition by reference_code,sku order by 1) = 1 )sc on lower(trim(replace(sc.reference_code,\'#\',\'\'))) = lower(trim(replace(ri.reference_code,\'#\',\'\'))) and lower(trim((sc.sku))) = lower(trim((ri.sku))) left join ( select marketplace_sku,Master_SKU, Title from `maplemonk.P_TAL_FINAL_SKU_MASTER` )cd on lower(trim(cd.marketplace_sku)) = trim(lower(ri.sku)) ) ) ; CREATE OR REPLACE TABLE MAPLEMONK.P_TAL_DB_easyecom_returns_fact_items AS SELECT IFNULL(FE.Source, \'NA\') AS Marketing_CHANNEL, FR.* FROM MAPLEMONK.P_TAL_DB_easyecom_returns_intermediate FR LEFT JOIN ( SELECT DISTINCT REPLACE(reference_code, \'#\', \'\') AS REFERENCE_CODE, Source FROM MAPLEMONK.P_TAL_DB_sales_consolidated ) FE ON FR.REFERENCE_CODE = FE.REFERENCE_CODE; CREATE OR REPLACE TABLE MAPLEMONK.P_TAL_DB_returns_consolidated AS SELECT UPPER(er.MARKETPLACE) AS Marketplace, mm.FINAL_MARKETPLACE, cast(RETURN_DATE as datetime) return_Date, UPPER(Marketing_CHANNEL) AS Marketing_channel, SUM(RETURNED_QUANTITY) AS TOTAL_RETURNED_QUANTITY, SUM(TOTAL_RETURN_AMOUNT) AS TOTAL_RETURN_AMOUNT, SUM(RETURN_TAX) AS TOTAL_RETURN_TAX, SUM(RETURN_AMOUNT_WITHOUT_TAX) AS TOTAL_RETURN_AMOUNT_EXCL_TAX FROM MAPLEMONK.P_TAL_DB_easyecom_returns_fact_items er LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from MAPLEMONK.marketplace_mapping ) where rw =1 ) mm ON lower(er.marketplace) = lower(mm.marketplace) GROUP BY er.Marketplace, mm.final_marketplace, RETURN_DATE, Marketing_channel;",
